#include <cstring>
namespace s5::pages
{
const PageImage* findImage (const std::string& id)
{
    for (int i = 0; i < kNumPageImages; ++i)
        if (id == kPageImages[i].id) return &kPageImages[i];
    return nullptr;
}

void drawImage (Screen& s, const PageImage& p)
{
    s.clear();
    int x = 0, y = 0;
    for (int i = 0; i < p.count; ++i)
    {
        const int col = p.rle[i] >> 12, len = p.rle[i] & 0xfff;
        if (col != 0) s.raw (x, y, len, 1, (Col) col);
        x += len;
        if (x >= kW) { x = 0; ++y; }
    }
}
}
